<?php require '../../../config/bootstrap.php';$u=require_auth();$s=db()->prepare('SELECT s.*,p.code plan_code,p.name plan_name,p.monthly_price_mzn,p.max_farms,p.max_devices,p.max_users FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.tenant_id=? ORDER BY s.id DESC LIMIT 1');$s->execute([$u['tenant_id']]);json_response(['subscription'=>$s->fetch()]);
